#!/usr/bin/env bash
# Run the orders example end to end on one machine: generate data, run the job with DqGuard and
# the OpenLineage listener; the DQ store and lineage go to $WORK (default: ./work).
#
#   bash examples/orders/run.sh                 # rules are generated by the agents (needs LLM_*)
#   DQ_AGENT_CHECKPOINTS=false bash examples/orders/run.sh   # DqGuard only, no LLM call
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
WORK="$(realpath -m "${WORK:-$ROOT/work}")"
JAR="$(ls "$ROOT"/target/lineage-dq-*.jar | head -1)"
OL_VERSION="${OL_VERSION:-1.53.0}"
mkdir -p "$WORK/lineage" "$WORK/data"

export DQ_STORE_LOCAL="$WORK/store"
export DQ_AGENT_DIR="$ROOT/dq-agents"
export DQ_AGENT_PYTHON="${DQ_AGENT_PYTHON:-python3}"
export DQ_AGENT_MODE=process_only
export DQ_WAREHOUSE_ENABLED=false
export DQ_BUSINESS_METADATA_YAML="$ROOT/examples/orders/metadata.yaml"
export DQ_LINEAGE_RAW_FILE="$WORK/lineage/orders-$(date +%Y%m%d-%H%M%S).ndjson"

[ -d "$WORK/data/orders" ] || spark-submit "$ROOT/examples/orders/gen_data.py" --out "$WORK/data"

spark-submit \
  --master "${SPARK_MASTER:-local[2]}" \
  --jars "$JAR" \
  --packages "io.openlineage:openlineage-spark_2.13:$OL_VERSION" \
  --conf spark.extraListeners=io.openlineage.spark.agent.OpenLineageSparkListener \
  --conf spark.openlineage.transport.type=file \
  --conf "spark.openlineage.transport.location=$DQ_LINEAGE_RAW_FILE" \
  --conf spark.openlineage.namespace=lineage-dq-example \
  --conf spark.openlineage.columnLineage.datasetLineageEnabled=true \
  --conf "spark.driver.extraJavaOptions=--add-opens=java.base/java.security=ALL-UNNAMED" \
  "$ROOT/examples/orders/job.py" --data "$WORK/data" --out "$WORK/out"

echo "DQ store: $DQ_STORE_LOCAL/dq   lineage: $DQ_LINEAGE_RAW_FILE"
